import { loadFont } from "@remotion/google-fonts/PlusJakartaSans";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// 123UPVIDEO. Motion vertical em inglês (público americano) do site 123upvideo.com: IA que expande o vídeo para outro
// formato preenchendo as bordas, sem cortar e sem barras pretas.
// Material: só o logo (duas versões). Pouco material → motion: a cena de vídeo é desenhada aqui (paisagem com duas pessoas)
// e serve de "vídeo do usuário". Problema (horizontal, recorte) com o mesmo desenho genérico; o produto entra em "Meet".
// Identidade do site: fundo quase preto azulado, ciano #1FD3EF, branco, Plus Jakarta Sans (a mesma do site).
// Limpo: fundo liso com brilho ciano leve atrás do destaque; o texto entra e fica parado; o movimento fica no quadro de vídeo.
// Tempos = tempos da voz editada (src/voz-en-v1-editada.wav, silêncio morto tirado; t = 0 é o começo do wav).

const { fontFamily: F } = loadFont("normal", { weights: ["500", "600", "700", "800"], subsets: ["latin"] });

export const UPV_FPS = 30;
export const LEAD = 0.15;
export const UPV_FRAMES = Math.round((35.88 + LEAD + 0.75) * UPV_FPS);
// v2: voz do Liam (americana), src/voz-en-liam-v1-editada.wav, 33,48 s. As cenas seguem escritas no tempo da voz v1;
// esta tabela (tempo novo → tempo v1, palavra por palavra, edit/tabela-liam.json) converte.
export const UPV_LIAM_FRAMES = Math.round((33.48 + LEAD + 0.75) * UPV_FPS);
const LIAM: [number, number][] = [[0.0, 0.0], [0.118, 0.102], [0.338, 0.342], [0.618, 0.622], [1.119, 1.162], [1.239, 1.322], [2.38, 2.503], [2.62, 2.803], [3.361, 3.863], [3.961, 4.464], [4.802, 5.554], [5.142, 5.874], [6.173, 6.815], [6.333, 6.955], [6.533, 7.095], [7.013, 7.415], [7.574, 8.285], [7.794, 8.465], [8.074, 8.686], [8.234, 8.806], [8.534, 9.066], [8.654, 9.186], [9.665, 10.206], [9.866, 10.446], [10.706, 11.367], [11.467, 12.147], [11.967, 13.227], [13.408, 14.048], [13.668, 14.328], [13.808, 14.468], [14.509, 15.348], [14.709, 15.548], [14.829, 15.648], [14.969, 15.788], [15.849, 16.428], [16.05, 16.728], [16.41, 17.629], [16.75, 17.989], [16.85, 18.109], [17.03, 18.269], [17.31, 18.649], [17.55, 18.909], [18.391, 19.559], [18.571, 19.739], [19.552, 20.94], [19.732, 21.1], [19.992, 21.34], [21.013, 22.204], [21.173, 22.344], [21.453, 22.585], [22.113, 23.586], [22.294, 23.907], [22.514, 24.127], [23.614, 25.16], [23.915, 25.42], [24.055, 25.6], [24.395, 25.901], [25.075, 26.922], [25.356, 27.183], [25.516, 27.363], [26.47, 28.436], [26.832, 28.756], [27.254, 29.297], [27.374, 29.457], [28.198, 30.339], [28.279, 30.439], [29.083, 31.311], [29.223, 31.471], [29.444, 31.531], [29.944, 32.031], [31.635, 33.614], [31.756, 33.735], [32.178, 34.255], [32.439, 34.476], [32.74, 34.816], [33.182, 35.517]];
const toV1 = (x: number) => {
  if (x <= 0) return x;
  const L = LIAM[LIAM.length - 1];
  if (x >= L[0]) return L[1] + (x - L[0]);
  let i = 1;
  while (LIAM[i][0] < x) i++;
  const [a0, a1] = LIAM[i - 1], [b0, b1] = LIAM[i];
  return a1 + ((x - a0) / (b0 - a0)) * (b1 - a1);
};

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.6));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const mix = (a: number, b: number, p: number) => a + (b - a) * p;
const bump = (t: number, a: number, d = 0.4) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI) * (1 - (t - a) / d));

const BG = "#05080D";
const CYAN = "#1FD3EF";
const WHITE = "#FFFFFF";
const SOFT = "#C9D3DE";
const GREY = "#7D8A99";
const CARD = "#0B1118";

// ---------- a cena desenhada (o "vídeo"): mundo de 1600 x 2844; o vídeo horizontal original é a faixa 972–1872 ----------
const WW = 1600;
const WH = 2844;
const BAND_Y = 972;
const BAND_H = 900;

const Person: React.FC<{ x: number; base: number; s?: number; flip?: boolean }> = ({ x, base, s = 1, flip }) => (
  <g transform={`translate(${x} ${base}) scale(${flip ? -s : s} ${s})`}>
    <circle cx={0} cy={-300} r={36} fill="#03070C" />
    <path d="M -58 -250 Q 0 -275 58 -250 L 66 -110 Q 60 -88 44 -86 L 40 0 L 8 0 L 4 -86 L -4 -86 L -8 0 L -40 0 L -44 -86 Q -60 -88 -66 -110 Z" fill="#03070C" />
    <path d="M 58 -250 L 66 -110" stroke="#5FD9F0" strokeOpacity={0.55} strokeWidth={5} fill="none" />
    <path d="M 26 -330 A 36 36 0 0 1 36 -296" stroke="#5FD9F0" strokeOpacity={0.6} strokeWidth={5} fill="none" />
  </g>
);

const stars = Array.from({ length: 70 }, (_, i) => {
  const a = Math.sin(i * 91.7) * 43758.5453;
  const b = Math.sin(i * 12.9 + 3) * 24634.6345;
  return { x: (a - Math.floor(a)) * WW, y: (b - Math.floor(b)) * 1150, r: 2 + ((i * 7) % 4) };
});

// o "vídeo" anda: nuvens passando, estrelas piscando, reflexo da lua tremendo, mato balançando
const World: React.FC<{ w: number }> = ({ w }) => {
  const tt = useCurrentFrame() / UPV_FPS;
  const wrap = (x: number) => ((x % 2400) + 2400) % 2400 - 400;
  return (
  <svg viewBox={`0 0 ${WW} ${WH}`} width={w} height={(w * WH) / WW} style={{ display: "block" }}>
    <defs>
      <linearGradient id="upv-sky" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stopColor="#030914" />
        <stop offset="0.45" stopColor="#071B33" />
        <stop offset="0.7" stopColor="#0E3A63" />
        <stop offset="0.9" stopColor="#3C8FBF" />
        <stop offset="1" stopColor="#A6DCEB" />
      </linearGradient>
      <linearGradient id="upv-water" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stopColor="#1A5A86" />
        <stop offset="0.25" stopColor="#0A2A45" />
        <stop offset="1" stopColor="#030A12" />
      </linearGradient>
      <radialGradient id="upv-moon" cx="0.5" cy="0.5" r="0.5">
        <stop offset="0" stopColor="#FFFFFF" stopOpacity="0.55" />
        <stop offset="1" stopColor="#FFFFFF" stopOpacity="0" />
      </radialGradient>
    </defs>
    <rect x={0} y={0} width={WW} height={1520} fill="url(#upv-sky)" />
    {stars.map((s, i) => (
      <circle key={i} cx={s.x} cy={s.y} r={s.r} fill="#FFFFFF" opacity={0.3 + 0.35 * (0.5 + 0.5 * Math.sin(tt * (2 + (i % 4)) + i))} />
    ))}
    <circle cx={1190} cy={1300} r={190} fill="url(#upv-moon)" />
    <circle cx={1190} cy={1300} r={64} fill="#F4FAFF" />
    {[
      { x: 100, y: 1080, rx: 260, ry: 34, v: 120, o: 0.22 },
      { x: 900, y: 1170, rx: 340, ry: 40, v: 90, o: 0.18 },
      { x: 1700, y: 1240, rx: 220, ry: 28, v: 150, o: 0.2 },
      { x: 500, y: 700, rx: 300, ry: 46, v: 70, o: 0.12 },
      { x: 1300, y: 420, rx: 280, ry: 40, v: 100, o: 0.1 },
    ].map((c, i) => (
      <ellipse key={`c${i}`} cx={wrap(c.x + c.v * tt)} cy={c.y} rx={c.rx} ry={c.ry} fill="#CFEFFF" opacity={c.o} />
    ))}
    <path d="M 0 1520 L 0 1330 L 180 1220 L 330 1300 L 520 1160 L 700 1290 L 860 1210 L 1040 1320 L 1260 1190 L 1440 1290 L 1600 1240 L 1600 1520 Z" fill="#14426A" />
    <path d="M 0 1520 L 0 1410 L 240 1340 L 430 1420 L 640 1350 L 900 1440 L 1120 1370 L 1360 1430 L 1600 1380 L 1600 1520 Z" fill="#0B2A46" />
    <rect x={0} y={1520} width={WW} height={WH - 1520} fill="url(#upv-water)" />
    {[0, 1, 2, 3, 4, 5].map((i) => (
      <rect key={i} x={1190 - 120 + i * 9 + 18 * Math.sin(tt * 3 + i * 1.7)} y={1545 + i * 34} width={240 - i * 18 + 30 * Math.sin(tt * 2.3 + i)} height={8} rx={4} fill="#DDF4FF" opacity={0.5 - i * 0.07} />
    ))}
    {/* margem em primeiro plano, onde as duas pessoas estão */}
    <path d="M 0 1660 Q 400 1600 800 1630 Q 1200 1655 1600 1610 L 1600 2844 L 0 2844 Z" fill="#0A1B2B" />
    <path d="M 0 1980 Q 500 1930 900 1990 Q 1300 2040 1600 1960 L 1600 2844 L 0 2844 Z" fill="#081626" />
    {[180, 330, 1270, 1430, 760].map((x, i) => (
      <ellipse key={x} cx={x} cy={2150 + (i % 3) * 170} rx={90 + (i % 2) * 50} ry={34} fill="#0A1A29" />
    ))}
    {[120, 260, 1340, 1500].map((x) => (
      <path key={x} transform={`rotate(${(6 * Math.sin(tt * 2.2 + x)).toFixed(2)} ${x} 1700)`} d={`M ${x} 1700 q -10 -60 -26 -90 M ${x} 1700 q 2 -70 6 -110 M ${x} 1700 q 12 -55 30 -80`} stroke="#0D2233" strokeWidth={8} fill="none" />
    ))}
    <Person x={585} base={1720} />
    <Person x={1015} base={1715} s={0.96} flip />
  </svg>
  );
};

// Janela sobre o mundo: (wx, wy, ww, wh) em coordenadas do mundo, mostrada com largura dw, centro em (cx, cy).
const Frame: React.FC<{
  wx: number; wy: number; ww: number; wh: number; dw: number; cx: number; cy: number;
  zoom?: number; panX?: number; radius?: number; border?: string; style?: React.CSSProperties; children?: React.ReactNode;
}> = ({ wx, wy, ww, wh, dw, cx, cy, zoom = 1, panX = 0, radius = 22, border, style, children }) => {
  const s = dw / ww;
  const dh = wh * s;
  return (
    <div style={{ position: "absolute", left: cx - dw / 2, top: cy - dh / 2, width: dw, height: dh, borderRadius: radius, overflow: "hidden", boxShadow: border ? `0 0 0 4px ${border}` : "0 30px 80px rgba(0,0,0,0.55)", ...style }}>
      <div style={{ position: "absolute", left: -wx * s, top: -wy * s, transformOrigin: `${(wx + ww / 2) * s}px ${(wy + wh / 2) * s}px`, transform: `translateX(${(-panX * s).toFixed(2)}px) scale(${zoom.toFixed(4)})` }}>
        <World w={WW * s} />
      </div>
      {children}
    </div>
  );
};

// ---------- textos ----------
const Title: React.FC<{ t: number; a: number; b: number; l1: React.ReactNode; l2?: React.ReactNode; l2at?: number; size?: number; y?: number }> = ({ t, a, b, l1, l2, l2at, size = 92, y = 400 }) => {
  if (t < a - 0.05 || t > b + 0.05) return null;
  const out = 1 - lin(t, b - 0.14, b);
  const e1 = k(t, a, 0.38);
  const e2 = k(t, l2at ?? a, 0.38);
  const line = (e: number): React.CSSProperties => ({ opacity: e * out, transform: `scale(${(0.92 + 0.08 * e).toFixed(4)})`, filter: `blur(${((1 - e) * 10).toFixed(2)}px)` });
  return (
    <div style={{ position: "absolute", left: 120, width: 840, top: y, transform: "translateY(-50%)", textAlign: "center", fontFamily: F, fontWeight: 800, fontSize: size, lineHeight: 1.06, letterSpacing: "-0.03em", color: WHITE }}>
      <div style={line(e1)}>{l1}</div>
      {l2 ? <div style={line(e2)}>{l2}</div> : null}
    </div>
  );
};
const Cy: React.FC<{ children: React.ReactNode }> = ({ children }) => <span style={{ color: CYAN }}>{children}</span>;

const Chip: React.FC<{ label: string; e: number; on?: boolean; size?: number }> = ({ label, e, on, size = 46 }) => (
  <div style={{ opacity: Math.min(1, e * 1.6), transform: `scale(${(0.6 + 0.4 * e).toFixed(4)})`, padding: "16px 34px 18px", borderRadius: 999, fontFamily: F, fontWeight: 700, fontSize: size, color: on ? BG : WHITE, background: on ? CYAN : "rgba(255,255,255,0.06)", border: `3px solid ${on ? CYAN : "rgba(255,255,255,0.22)"}`, boxShadow: on ? `0 0 34px rgba(31,211,239,0.45)` : "none", whiteSpace: "nowrap" }}>{label}</div>
);

const Glow: React.FC<{ cy: number; o: number; r?: number }> = ({ cy, o, r = 620 }) => (
  <div style={{ position: "absolute", left: 540 - r, top: cy - r, width: r * 2, height: r * 2, borderRadius: "50%", background: "radial-gradient(circle, rgba(31,211,239,0.22) 0%, rgba(31,211,239,0.08) 40%, rgba(31,211,239,0) 70%)", opacity: o }} />
);

// ---------- ícones ----------
const IconCam: React.FC = () => (
