  <svg viewBox="0 0 40 40" width={70} height={70}>
    <path d="M 6 4 L 6 32 L 13 25 L 18 36 L 23 34 L 18 23 L 28 23 Z" fill={WHITE} stroke={BG} strokeWidth={2.5} strokeLinejoin="round" />
  </svg>
);

// planos do "vídeo" horizontal (zoom, panorâmica em x do mundo): um corte a cada palavra forte, deriva dentro do plano
const SHOTS = [
  { a: -1, b: 1.3, z: [1.65, 1.4], p: [-300, -160] },
  { a: 1.3, b: 2.8, z: [1.0, 1.08], p: [0, 40] },
  { a: 2.8, b: 3.86, z: [2.2, 2.0], p: [330, 290] },
  { a: 3.86, b: 4.66, z: [1.8, 1.7], p: [-260, -210] },
  { a: 4.66, b: 5.87, z: [1.35, 1.25], p: [150, 110] },
  { a: 5.87, b: 99, z: [1.06, 1.0], p: [0, 0] },
];
const shot = (t: number) => {
  const c = SHOTS.find((x) => t >= x.a && t < x.b) ?? SHOTS[SHOTS.length - 1];
  const p = interpolate(t, [Math.max(c.a, -0.15), Math.min(c.b, 6.8)], [0, 1], { ...cl, easing: OUT });
  return { zoom: mix(c.z[0], c.z[1], p), panX: mix(c.p[0], c.p[1], p) };
};

// ---------- composição ----------
export const Upvideo: React.FC<{ voz?: "kaique" | "liam" }> = ({ voz = "kaique" }) => {
  const frame = useCurrentFrame();
  const t = voz === "liam" ? toV1(frame / UPV_FPS - LEAD) : frame / UPV_FPS - LEAD;

  // ===== A · 0–2,5: "Your best video is horizontal." =====
  const aOn = t < 2.62;
  const aW = interpolate(t, [-0.15, 0.25], [260, 840], { ...cl, easing: OUT });
  const aH = interpolate(t, [0.1, 0.5], [12, 472.5], { ...cl, easing: OUT });
  // ===== B · 2,5–6,8: chips e o celular vertical com barras pretas =====
  const bShrink = io(t, 2.5, 3.15);
  const bPhone = k(t, 2.62, 0.5);
  const bOut = io(t, 6.72, 7.05);
  const phonePulse = bump(t, 5.87, 0.6);
  // ===== C · 6,8–10,2: recorte =====
  const cIn = io(t, 6.78, 7.2);
  const cBox = pop(t, 7.09, 0.4);
  const cDim = k(t, 7.42, 0.35);
  const cFly = io(t, 8.29, 8.85);
  const cGrow = io(t, 8.45, 9.0);
  const shake = bump(t, 9.19, 0.5);
  // ===== D · 10,2–14: "Not anymore." (cortina ciano) e o logo =====
  const wipeIn = io(t, 10.0, 10.28);
  const wipeOut = io(t, 11.12, 11.4);
  const logoE = pop(t, 12.1, 0.6);
  const logoOut = io(t, 13.8, 14.1);
  // ===== E · 14–19,5: upload, formato, expansão =====
  const eCard = k(t, 13.95, 0.5);
  const eDrop = pop(t, 14.1, 0.55);
  const eBtn = k(t, 14.35, 0.4) * (1 - io(t, 15.2, 15.35));
  const eChips = 1 - io(t, 16.35, 16.6);
  const eSel = io(t, 15.79, 16.0);
  const eCardOut = io(t, 16.35, 16.7);
  const eExp = io(t, 16.73, 17.9);
  // ===== F · 19,5–25,1: sem corte, qualquer formato =====
  const f11 = io(t, 23.85, 24.15);
  const f45 = io(t, 24.3, 24.6);
  const f916 = io(t, 24.75, 25.0);
  const fOut = io(t, 25.0, 25.4);
  // ===== G · 25,1–28,3: para quem =====
  const g1 = pop(t, 25.85, 0.5);
  const g2 = pop(t, 27.12, 0.5);
  const gOut = io(t, 28.15, 28.45);
  // ===== H · 28,3–31,2: preço =====
  const hIn = pop(t, 29.36, 0.5);
  const hCount = io(t, 29.4, 30.05);
  const hMo = k(t, 30.3, 0.4);
  const hOut = io(t, 31.05, 31.35);
  // ===== I · 31,2–fim: chamada =====
  const iLogo = k(t, 31.2, 0.6);
  const iUrl = pop(t, 31.5, 0.55);
  const iTxt = k(t, 33.7, 0.4);
  const iCur = io(t, 33.2, 34.6);
  const iClick = bump(t, 34.62, 0.35);
  const iRipple = lin(t, 34.62, 35.3);

  // posição/forma do quadro de vídeo ao longo de A–C
  const frameDw = t < 6.75 ? mix(840, 450, bShrink) : mix(450, 840, cIn);
  const frameCy = t < 6.75 ? mix(1090, 1120, bShrink) : mix(1120, 1090, cIn);

  // janela do quadro ao longo de E–F
  const exWy = mix(BAND_Y, 0, eExp);
  const exWh = mix(BAND_H, WH, eExp);
  let fWy = exWy, fWh = exWh, fDw = mix(600, 560, eExp);
  if (t > 23.8) {
    // 9:16 → 1:1 → 4:5 → 9:16
    const c = BAND_Y + BAND_H / 2 + 150;
    const r = (h: number) => ({ wy: c - h / 2 + 0, wh: h });
    const s916 = { wy: 0, wh: WH, dw: 560 };
    const s11 = { ...r(1600), dw: 760 };
    const s45 = { ...r(2000), dw: 700 };
    const lerp = (A: typeof s916, B: typeof s916, p: number) => ({ wy: mix(A.wy, B.wy, p), wh: mix(A.wh, B.wh, p), dw: mix(A.dw, B.dw, p) });
    let v = lerp(s916, s11, f11);
    if (t > 24.3) v = lerp(s11, s45, f45);
    if (t > 24.75) v = lerp(s45, s916, f916);
    fWy = Math.max(0, Math.min(WH - v.wh, v.wy));
    fWh = v.wh;
    fDw = v.dw;
  }
  const ratioLabel = t < 23.85 ? "9:16" : t < 24.3 ? "1:1" : t < 24.75 ? "4:5" : "9:16";
  const eCy = mix(1010, 1150, eCardOut);

  return (
    <AbsoluteFill style={{ background: BG, overflow: "hidden" }}>
      {/* brilho leve atrás do destaque de cada trecho */}
      <Glow cy={1090} o={t < 10 ? 0.9 : t < 28.3 ? 0.7 : 0} />
      <Glow cy={1000} o={hIn * (1 - hOut)} r={560} />
      <Glow cy={900} o={iLogo} r={640} />

      {/* ---------- A + B: o vídeo horizontal ---------- */}
      {t < 6.8 ? (
        <>
          {/* celular 9:16 (B) */}
          <div style={{ position: "absolute", left: 540 - 240, top: 1120 - 426.5, width: 480, height: 853, borderRadius: 56, overflow: "hidden", background: "#000", boxShadow: `0 0 0 6px ${phonePulse > 0 ? CYAN : "rgba(255,255,255,0.28)"}, 0 0 ${(60 * phonePulse).toFixed(1)}px rgba(31,211,239,${(0.6 * phonePulse).toFixed(3)}), 0 40px 90px rgba(0,0,0,0.6)`, opacity: bPhone * (1 - bOut), transform: `rotate(${((1 - io(t, 2.55, 3.1)) * -90).toFixed(2)}deg) scale(${(0.86 + 0.14 * bPhone + 0.04 * phonePulse).toFixed(4)})` }}>
            {/* feed rolando: um post por plataforma citada, todos com o vídeo deitado e barras pretas */}
            {t >= 3.15 ? (() => {
              const sw = io(t, 3.86, 4.18) + io(t, 4.66, 4.98);
              const posts = [shot(t), { zoom: mix(1.9, 1.75, lin(t, 3.86, 4.7)), panX: -230 }, { zoom: mix(1.4, 1.25, lin(t, 4.66, 6.8)), panX: mix(160, 100, lin(t, 4.66, 6.8)) }];
